#[allow(non_camel_case_types, dead_code)]
#[derive(Clone)]
pub struct CompilationUnitContext<'a, State = StoredTreeContext> {
    __node: __GeneratedRuleContext<'a>,
    __invocation_states: Option<Vec<isize>>,
    __state: std::marker::PhantomData<State>,
}

impl<'a> FromRuleNode<'a> for CompilationUnitContext<'a> {
    fn from_rule_node(node: RuleNodeView<'a>) -> Option<Self> {
        if node.rule_index() != 0 { return None; }
        Some(Self::__from_node(node))
    }
}

impl<'a> AsRuleNode<'a> for CompilationUnitContext<'a> {
    fn as_rule_node(&self) -> RuleNodeView<'a> { self.rule_node() }
}

impl<'a> CompilationUnitContext<'a> {
    pub fn rule_node(&self) -> RuleNodeView<'a> {
        match self.__node {
            __GeneratedRuleContext::Stored(node) => node,
            __GeneratedRuleContext::Active { .. } => unreachable!("stored context type contains an active parser context"),
        }
    }
}

impl<'a> __FromActiveRuleContext<'a> for CompilationUnitContext<'a, __ActiveParserContext> {
    fn __from_active(
        context: &'a antlr4_runtime::ParserRuleContext,
        invocation_states: Vec<isize>,
        storage: &'a antlr4_runtime::ParseTreeStorage,
        tokens: &'a antlr4_runtime::TokenStore,
    ) -> Option<Self> {
        if context.rule_index() != 0 { return None; }
        Some(Self {
            __node: __GeneratedRuleContext::Active { context, storage, tokens },
            __invocation_states: Some(invocation_states),
            __state: std::marker::PhantomData,
        })
    }
}

impl<'a> FromValidatedRuleNode<'a> for CompilationUnitContext<'a, ValidatedTreeContext> {
    fn from_validated_rule_node(node: ValidatedRuleNode<'a>) -> Option<Self> {
        let node = node.rule_node();
        if node.rule_index() != 0 { return None; }
        Some(Self::__from_validated_node(node))
    }
}

impl<'a> AsRuleNode<'a> for CompilationUnitContext<'a, ValidatedTreeContext> {
    fn as_rule_node(&self) -> RuleNodeView<'a> { self.rule_node() }
}

#[allow(dead_code, clippy::all)]
impl<'a> CompilationUnitContext<'a> {
    fn __from_node(node: RuleNodeView<'a>) -> Self {
        Self::__from_node_with_invocation_states(node, None)
    }

    fn __from_child_node(
        node: RuleNodeView<'a>,
        parent_invocation_states: Option<&[isize]>,
    ) -> Self {
        let invocation_states = parent_invocation_states.map(|states| {
            let mut invocation_states = Vec::with_capacity(states.len() + 1);
            invocation_states.push(node.invoking_state());
            invocation_states.extend_from_slice(states);
            invocation_states
        });
        Self::__from_node_with_invocation_states(node, invocation_states)
    }

    fn __from_listener_node(node: RuleNodeView<'a>, invocation_states: Option<&[isize]>) -> Self {
        Self::__from_node_with_invocation_states(
            node,
            invocation_states.map(|states| states.to_vec()),
        )
    }

    fn __from_node_with_invocation_states(
        node: RuleNodeView<'a>,
        invocation_states: Option<Vec<isize>>,
    ) -> Self {
        Self {
            __node: __GeneratedRuleContext::Stored(node),
            __invocation_states: invocation_states,
            __state: std::marker::PhantomData,
        }
    }

}

#[allow(dead_code, clippy::all)]
impl<'a, State> CompilationUnitContext<'a, State> {
    pub fn child_count(&self) -> usize {
        match &self.__node {
            __GeneratedRuleContext::Stored(node) => node.child_count(),
            __GeneratedRuleContext::Active { context, .. } => context.child_count(),
        }
    }

    /// Iterates terminals owned directly by this context without descending
    /// into nested rule contexts.
    ///
    /// Recovered trees expose inserted and deleted recovery tokens as error
    /// nodes through the same `TerminalNode` surface. Use
    /// `TerminalNode::is_error()` to identify recovery nodes and
    /// `TerminalNode::is_missing()` to identify inserted synthetic tokens.
    pub fn direct_terminals(
        &self,
    ) -> impl Iterator<Item = TerminalNode<'a>> + 'a + use<'a, State> {
        __terminal_children(self.__node).map(TerminalNode::new)
    }

    pub fn start(&self) -> __GeneratedTokenView {
        let token = match &self.__node {
            __GeneratedRuleContext::Stored(node) => node.start(),
            __GeneratedRuleContext::Active { context, tokens, .. } => context.start(tokens),
        };
        __GeneratedTokenView { text: token.map(|token| token.text_or_empty().to_owned()).unwrap_or_default() }
    }

    pub fn text(&self) -> String {
        match &self.__node {
            __GeneratedRuleContext::Stored(node) => node.text(),
            __GeneratedRuleContext::Active { context, storage, tokens } => context.text(storage, tokens),
        }
    }
}

#[allow(dead_code, private_bounds, clippy::all)]
impl<'a, State: __RecoveryContextState> CompilationUnitContext<'a, State> {
    pub fn modular_compulation_unit(&self) -> Option<ModularCompulationUnitContext<'a>> {
        __rule_children(self.__node, 1)
            .next()
            .map(|node| ModularCompulationUnitContext::__from_child_node(node, self.__invocation_states.as_deref()))
    }
    pub fn package_declaration(&self) -> Option<PackageDeclarationContext<'a>> {
        __rule_children(self.__node, 2)
            .next()
            .map(|node| PackageDeclarationContext::__from_child_node(node, self.__invocation_states.as_deref()))
    }
    pub fn import_declaration_children(&self) -> impl Iterator<Item = ImportDeclarationContext<'a>> + '_ {
        __rule_children(self.__node, 3)
            .map(move |node| ImportDeclarationContext::__from_child_node(node, self.__invocation_states.as_deref()))
    }
    pub fn type_declaration_children(&self) -> impl Iterator<Item = TypeDeclarationContext<'a>> + '_ {
        __rule_children(self.__node, 4)
            .map(move |node| TypeDeclarationContext::__from_child_node(node, self.__invocation_states.as_deref()))
    }
    pub fn eof_token(&self) -> Result<TerminalNode<'a>, MissingChildError> {
        __token_children(self.__node, -1)
            .next()
            .map(TerminalNode::new)
            .ok_or_else(|| MissingChildError::new("CompilationUnitContext", "EOF"))
    }
    pub fn semi_tokens(&self) -> impl Iterator<Item = TerminalNode<'a>> + '_ {
        __token_children(self.__node, 85).map(TerminalNode::new)
    }
}

